29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date", columnDefinition = "DATE")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    @Column(name = "bulk_signup_warning")
78	    private boolean bulkSignupWarning;
79	
80	    @Column(name = "possible_duplicate")
81	    private boolean possibleDuplicate;
82	
83	    @Column(name = "possible_duplicate_of")
84	    private Integer possibleDuplicateOf;
85	
86	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
87	    private Set<Pet> pets;
88	
89	    public String getAddress() {
90	        return this.address;
91	    }
92	
93	    public void setAddress(String address) {
94	        this.address = address;
95	    }
96	
97	    public String getCity() {
98	        return this.city;
99	    }
100	
101	    public void setCity(String city) {
102	        this.city = city;
103	    }
104	
105	    public String getTelephone() {
106	        return this.telephone;
107	    }
108	
109	    public void setTelephone(String telephone) {
110	        this.telephone = telephone;
111	    }
112	
113	    public String getEmail() {
114	        return this.email;
115	    }
116	
117	    /**
118	     * Stores the email in its canonical lower-cased form so it is always persisted and
119	     * returned lower-cased, regardless of the casing supplied by the client.
120	     */
121	    public void setEmail(String email) {
122	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
123	    }
124	
125	    public String getPostcode() {
126	        return this.postcode;
127	    }
128	
129	    public void setPostcode(String postcode) {
130	        this.postcode = postcode;
131	    }
132	
133	    public LocalDate getRegistrationDate() {
134	        return this.registrationDate;
135	    }
136	
137	    public void setRegistrationDate(LocalDate registrationDate) {
138	        this.registrationDate = registrationDate;
139	    }
140	
141	    public LocalDate getBirthDate() {
142	        return this.birthDate;
143	    }
144	
145	    public void setBirthDate(LocalDate birthDate) {
146	        this.birthDate = birthDate;
147	    }
148	
149	    /**
150	     * The owner's tenure in days: the number of whole days from its {@link #registrationDate} to
151	     * the current date. A brand-new owner registered today has zero tenure.
152	     */
153	    @Transient
154	    public long getTenureDays() {
155	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
156	    }
157	
158	    /**
159	     * The owner's age band derived from {@link #birthDate} against {@link #registrationDate}, or
160	     * {@code null} when no birth date was supplied.
161	     */
162	    @Transient
163	    public AgeBand getAgeBand() {
164	        return this.birthDate == null ? null : AgeBand.of(this.birthDate, this.registrationDate);
165	    }
166	
167	    public String getCustomerCode() {
168	        return this.customerCode;
169	    }
170	
171	    public void setCustomerCode(String customerCode) {
172	        this.customerCode = customerCode;
173	    }
174	
175	    public String getHouseholdId() {
176	        return this.householdId;
177	    }
178	
179	    public void setHouseholdId(String householdId) {
180	        this.householdId = householdId;
181	    }
182	
183	    public Integer getNamesakeCount() {
184	        return this.namesakeCount;
185	    }
186	
187	    public void setNamesakeCount(Integer namesakeCount) {
188	        this.namesakeCount = namesakeCount;
189	    }
190	
191	    public Integer getHouseholdSize() {
192	        return this.householdSize;
193	    }
194	
195	    public void setHouseholdSize(Integer householdSize) {
196	        this.householdSize = householdSize;
197	    }
198	
199	    public boolean isBulkSignupWarning() {
200	        return this.bulkSignupWarning;
201	    }
202	
203	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
204	        this.bulkSignupWarning = bulkSignupWarning;
205	    }
206	
207	    public boolean isPossibleDuplicate() {
208	        return this.possibleDuplicate;
209	    }
210	
211	    public void setPossibleDuplicate(boolean possibleDuplicate) {
212	        this.possibleDuplicate = possibleDuplicate;
213	    }
214	
215	    public Integer getPossibleDuplicateOf() {
216	        return this.possibleDuplicateOf;
217	    }
218	
219	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
220	        this.possibleDuplicateOf = possibleDuplicateOf;
221	    }
222	
223	    /**
224	     * The derived key that uniquely identifies an owner for duplicate detection: the normalized
225	     * telephone, the (lower-cased) email or the empty string when absent, and the household id or
226	     * the empty string when the owner belongs to no household, joined with {@code '|'}. Two owners
227	     * are duplicates only when their whole identity keys are equal, so members of the same household
228	     * with different telephones (or an owner reusing only a telephone or only an email) remain
229	     * distinct.
230	     */
231	    @Transient
232	    public String getIdentityKey() {
233	        return this.telephone + "|"
234	            + (this.email == null ? "" : this.email) + "|"
235	            + (this.householdId == null ? "" : this.householdId);
236	    }
237	
238	    /**
239	     * On first persist, default the registration date to the server's current date when the
240	     * client did not supply one, then roll the effective date forward so it always falls on a
241	     * business day (a weekend moves to the following Monday).
242	     */
243	    @PrePersist
244	    private void defaultRegistrationDate() {
245	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
246	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
247	    }
248	
249	    protected Set<Pet> getPetsInternal() {
250	        if (this.pets == null) {
251	            this.pets = new HashSet<>();
252	        }
253	        return this.pets;
254	    }
255	
256	    protected void setPetsInternal(Set<Pet> pets) {
257	        this.pets = pets;
258	    }
259	
260	    public List<Pet> getPets() {
261	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
262	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
263	        return Collections.unmodifiableList(sortedPets);
264	    }
265	
266	    public void setPets(List<Pet> pets) {
267	        this.pets = new HashSet<>(pets);
268	    }
269	
270	    public void addPet(Pet pet) {
271	        getPetsInternal().add(pet);
272	        pet.setOwner(this);
273	    }
274	
275	    /**
276	     * Return the Pet with the given name, or null if none found for this Owner.
277	     *
278	     * @param name to test
279	     * @return true if pet name is already in use
280	     */
281	    public Pet getPet(String name) {
282	        return getPet(name, false);
283	    }
284	
285	    /**
286	     * Return the Pet with the given name, or null if none found for this Owner.
287	     *
288	     * @param name to test
289	     * @return true if pet name is already in use
290	     */
291	    public Pet getPet(String name, boolean ignoreNew) {
292	        name = name.toLowerCase();
293	        for (Pet pet : getPetsInternal()) {
294	            if (!ignoreNew || !pet.isNew()) {
295	                String compName = pet.getName();
296	                compName = compName.toLowerCase();
297	                if (compName.equals(name)) {
298	                    return pet;
299	                }
300	            }
301	        }
302	        return null;
303	    }
304	
305	    public Pet getPet(Integer petId) {
306	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
307	    }
308	
309	    @Override
310	    public String toString() {
311	        return new ToStringCreator(this)
312	
313	            .append("id", this.getId())
314	            .append("new", this.isNew())
315	            .append("lastName", this.getLastName())
316	            .append("firstName", this.getFirstName())
317	            .append("address", this.address)
318	            .append("city", this.city)
319	            .append("telephone", this.telephone)
320	            .append("email", this.email)
321	            .toString();
322	    }
323	}
