1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Validates an owner's postcode against its city using {@link PostcodeRule}. On failure the
10	 * violation is reported against the {@code postcode} property.
11	 */
12	public class PostcodeValidator implements ConstraintValidator<ValidPostcode, OwnerFieldsDto> {
13	
14	    @Override
15	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
16	        if (owner == null || PostcodeRule.isValid(owner.getCity(), owner.getPostcode())) {
17	            return true;
18	        }
19	        context.disableDefaultConstraintViolation();
20	        context.buildConstraintViolationWithTemplate(context.getDefaultConstraintMessageTemplate())
21	            .addPropertyNode("postcode")
22	            .addConstraintViolation();
23	        return false;
24	    }
25	}
