1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import jakarta.validation.Constraint;
4	import jakarta.validation.Payload;
5	import java.lang.annotation.*;
6	
7	/**
8	 * Class-level constraint validating an owner's {@code postcode} against its {@code city}: when a
9	 * postcode is present it must be four digits and, for a city with a known region, fall within that
10	 * region's fixed range (see {@link PostcodeRule}). An absent postcode is always accepted.
11	 */
12	@Target({ ElementType.TYPE })
13	@Retention(RetentionPolicy.RUNTIME)
14	@Constraint(validatedBy = PostcodeValidator.class)
15	@Documented
16	public @interface ValidPostcode {
17	
18	    String message() default "Postcode must be 4 digits and valid for the city's region";
19	
20	    Class<?>[] groups() default {};
21	
22	    Class<? extends Payload>[] payload() default {};
23	}
