16	package org.springframework.samples.petclinic.service;
17	
18	import org.slf4j.Logger;
19	import org.slf4j.LoggerFactory;
20	import org.springframework.samples.petclinic.mapper.OwnerMapper;
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Emits audit records for owner life-cycle events to the dedicated {@code AUDIT}
26	 * logger, keeping audit side-effects separate from the create business logic.
27	 */
28	@Component
29	public class OwnerAuditor {
30	
31	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
32	
33	    private final OwnerMapper ownerMapper;
34	
35	    public OwnerAuditor(OwnerMapper ownerMapper) {
36	        this.ownerMapper = ownerMapper;
37	    }
38	
39	    /**
40	     * Record the successful creation of an owner, capturing its id, customer code,
41	     * registration date and derived membership number and level.
42	     */
43	    public void auditCreated(Owner owner) {
44	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipNumber={} membershipLevel={}",
45	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
46	            this.ownerMapper.formatMembershipNumber(owner), this.ownerMapper.resolveMembershipLevel(owner));
47	    }
48	}
