16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Locale;
19	import java.util.function.Predicate;
20	
21	import org.springframework.samples.petclinic.rest.validation.LocalityResolver;
22	import org.springframework.samples.petclinic.util.Sha256;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Builds an owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
27	 * canonical region derived from the owner's postcode and HASH8 is the first eight upper-case hex
28	 * characters of the SHA-256 of the owner's normalized telephone concatenated with the last name
29	 * (e.g. {@code "NSW-1A2B3C4D"}).
30	 */
31	@Component
32	public class CustomerCodeGenerator {
33	
34	    /** Number of leading hex characters of the SHA-256 digest kept as the identity hash. */
35	    private static final int HASH_LENGTH = 8;
36	
37	    /**
38	     * Build the customer code for the given postcode, normalized telephone and last name.
39	     *
40	     * @param postcode            the owner's postcode; its region forms the leading segment
41	     * @param normalizedTelephone the owner's telephone in canonical (E.164) form; hashed with the
42	     *                            last name to form the trailing segment
43	     * @param lastName            the owner's last name; hashed with the telephone
44	     * @return the formatted customer code
45	     */
46	    public String generate(String postcode, String normalizedTelephone, String lastName) {
47	        String region = LocalityResolver.resolveFromPostcode(postcode);
48	        String hash = Sha256.hex(normalizedTelephone + lastName)
49	            .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
50	        return region + "-" + hash;
51	    }
52	
53	    /**
54	     * Return a customer code that no existing owner already carries. If {@code customerCode} is free
55	     * it is returned unchanged; otherwise {@code "-<n>"} is appended using the smallest {@code n} of
56	     * two or more that yields an unused code.
57	     *
58	     * @param customerCode the freshly generated code that may collide with an existing owner's code
59	     * @param isTaken      predicate reporting whether a candidate code is already in use
60	     * @return a code guaranteed not to collide with an existing owner's code
61	     */
62	    public String deduplicate(String customerCode, Predicate<String> isTaken) {
63	        if (!isTaken.test(customerCode)) {
64	            return customerCode;
65	        }
66	        for (int n = 2; ; n++) {
67	            String candidate = customerCode + "-" + n;
68	            if (!isTaken.test(candidate)) {
69	                return candidate;
70	            }
71	        }
72	    }
73	}
