23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
28	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
29	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
30	    @Mapping(target = "locality", expression = "java(resolveLocality(owner))")
31	    @Mapping(target = "timezone", expression = "java(resolveTimezone(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(computeCheckDigit(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(resolveMembershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(resolveMembershipLevel(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(resolveContactPreference(owner))")
37	    @Mapping(target = "ageBand", expression = "java(resolveAgeBand(owner))")
38	    @Mapping(target = "identityKey", expression = "java(owner.getIdentityKey())")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    Owner toOwner(OwnerDto ownerDto);
42	
43	    /**
44	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
45	     */
46	    default String formatDisplayName(Owner owner) {
47	        return owner.getLastName() + ", " + owner.getFirstName();
48	    }
49	
50	    /**
51	     * Formats the owner's stored E.164 telephone for human display (country code, a space and the
52	     * national digits grouped in threes), leaving the raw {@code telephone} in E.164 form.
53	     */
54	    default String formatTelephoneDisplay(Owner owner) {
55	        return TelephoneFormatter.toDisplay(owner.getTelephone());
56	    }
57	
58	    /**
59	     * Formats the owner's initials as the upper-cased first letters of firstName and
60	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
61	     */
62	    default String formatInitials(Owner owner) {
63	        return initial(owner.getFirstName()) + initial(owner.getLastName());
64	    }
65	
66	    /** The upper-cased first letter of {@code name} followed by a dot. */
67	    private String initial(String name) {
68	        return Character.toUpperCase(name.charAt(0)) + ".";
69	    }
70	
71	    /**
72	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
73	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
74	     * region encoded in the owner's identity.
75	     */
76	    default String resolveLocality(Owner owner) {
77	        String customerCode = owner.getCustomerCode();
78	        return customerCode.substring(0, customerCode.indexOf('-'));
79	    }
80	
81	    /**
82	     * Derives the owner's IANA timezone from its {@linkplain #resolveLocality(Owner) locality}
83	     * (canonical region) via the fixed region-to-timezone table, or {@code null} when the locality
84	     * has no known timezone.
85	     */
86	    default String resolveTimezone(Owner owner) {
87	        return TimezoneResolver.resolve(resolveLocality(owner));
88	    }
89	
90	    /**
91	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
92	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
93	     */
94	    default String formatMembershipNumber(Owner owner) {
95	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
96	    }
97	
98	    /**
99	     * Computes the Luhn check digit over the decimal digits of the owner's customer code.
100	     */
101	    default Integer computeCheckDigit(Owner owner) {
102	        return Luhn.checkDigit(owner.getCustomerCode());
103	    }
104	
105	    /** The minimum tenure, in days, an owner must exceed to earn the tenure membership points. */
106	    int TENURE_POINTS_THRESHOLD_DAYS = 365;
107	
108	    /** The minimum household size that earns the household membership points. */
109	    int HOUSEHOLD_POINTS_THRESHOLD = 3;
110	
111	    /**
112	     * Resolves the owner's membership points: starts at {@code 0}, plus {@code 2} when an email is
113	     * present, plus {@code 1} when the owner has no namesakes (namesakeCount is 0), plus {@code 2}
114	     * when the owner belongs to a household of {@value #HOUSEHOLD_POINTS_THRESHOLD} or more, plus
115	     * {@code 3} when the owner's tenure exceeds {@value #TENURE_POINTS_THRESHOLD_DAYS} days.
116	     */
117	    default Integer resolveMembershipPoints(Owner owner) {
118	        int points = 0;
119	        if (hasEmail(owner)) {
120	            points += 2;
121	        }
122	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
123	            points += 1;
124	        }
125	        Integer householdSize = owner.getHouseholdSize();
126	        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
127	            points += 2;
128	        }
129	        if (owner.getTenureDays() > TENURE_POINTS_THRESHOLD_DAYS) {
130	            points += 3;
131	        }
132	        return points;
133	    }
134	
135	    /**
136	     * Resolves the owner's numeric membership level from its {@linkplain #resolveMembershipPoints
137	     * membership points}: level {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
138	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more.
139	     */
140	    default Integer resolveMembershipLevel(Owner owner) {
141	        int points = resolveMembershipPoints(owner);
142	        if (points <= 1) {
143	            return 1;
144	        }
145	        if (points <= 3) {
146	            return 2;
147	        }
148	        if (points <= 5) {
149	            return 3;
150	        }
151	        return 4;
152	    }
153	
154	    /**
155	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
156	     * present, otherwise {@code "PHONE"}.
157	     */
158	    default String resolveContactPreference(Owner owner) {
159	        return hasEmail(owner) ? "EMAIL" : "PHONE";
160	    }
161	
162	    /** Whether the owner has a non-blank email address. */
163	    private boolean hasEmail(Owner owner) {
164	        return owner.getEmail() != null && !owner.getEmail().isBlank();
165	    }
166	
167	    /**
168	     * Resolves the owner's age band (as a string) from its birth date against its registration
169	     * date, or {@code null} when the owner has no birth date.
170	     */
171	    default String resolveAgeBand(Owner owner) {
172	        return owner.getAgeBand() == null ? null : owner.getAgeBand().name();
173	    }
174	
175	    @Mapping(target = "id", ignore = true)
176	    @Mapping(target = "pets", ignore = true)
177	    @Mapping(target = "householdId", ignore = true)
178	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
179	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
180	    Owner toOwner(OwnerFieldsDto ownerDto);
181	
182	    /**
183	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
184	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
185	     */
186	    @Named("normalizeAddress")
187	    default String normalizeAddress(String address) {
188	        return AddressNormalizer.normalize(address);
189	    }
190	
191	    /**
192	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
193	     * the raw value normalizes to a valid E.164 number.
194	     */
195	    @Named("normalizeTelephone")
196	    default String normalizeTelephone(String telephone) {
197	        return TelephoneNormalizer.toE164(telephone);
198	    }
199	
200	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
201	
202	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
203	
204	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
205	        OwnerPageDto ownerPageDto = new OwnerPageDto();
206	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
207	        ownerPageDto.setPage(ownerPage.getNumber());
208	        ownerPageDto.setSize(ownerPage.getSize());
209	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
210	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
211	        return ownerPageDto;
212	    }
213	}
