17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Utility for computing the SHA-256 hash of a string as hexadecimal.
25	 */
26	public final class Sha256 {
27	
28	    private Sha256() {
29	    }
30	
31	    /**
32	     * Compute the SHA-256 digest of the UTF-8 bytes of {@code value}, rendered as a 64-character
33	     * lower-case hexadecimal string.
34	     *
35	     * @param value the string to hash
36	     * @return the lower-case hex SHA-256 of {@code value}
37	     */
38	    public static String hex(String value) {
39	        try {
40	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(digest.length * 2);
42	            for (byte b : digest) {
43	                sb.append(String.format("%02x", b));
44	            }
45	            return sb.toString();
46	        } catch (NoSuchAlgorithmException e) {
47	            throw new IllegalStateException("SHA-256 not available", e);
48	        }
49	    }
50	}
