79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        if (this.clinicService.isRegistrationDateInFuture(owner.getRegistrationDate())) {
110	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
111	        }
112	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
113	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
114	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
115	        }
116	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        // Assign the deterministic householdId (derived from last name and postcode) so owners in
120	        // the same household share it automatically and it forms part of the identity key.
121	        this.clinicService.assignHousehold(owner);
122	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
123	        // A second owner in an existing household (same last name and postcode) is a household
124	        // duplicate; reject it unless the client declares the shared household, in which case it is
125	        // created as a declared member.
126	        if (this.clinicService.existsOwnerInHousehold(owner) && !declaredHouseholdMember) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        // Reject an exact duplicate: an owner whose whole identity key (normalized telephone,
130	        // email and householdId) already exists.
131	        if (this.clinicService.existsOwnerWithIdentityKey(owner)) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
135	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner));
136	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
137	        // Flag a soft match unless this is a declared household member (a declared member is not a
138	        // suspected duplicate): an existing owner sharing this owner's last name and postcode with a
139	        // different telephone.
140	        if (!declaredHouseholdMember) {
141	            Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
142	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
143	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
144	        }
145	        this.clinicService.saveOwner(owner);
146	        this.ownerAuditor.auditCreated(owner);
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
156	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
157	        if (currentOwner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        currentOwner.setAddress(ownerFieldsDto.getAddress());
161	        currentOwner.setCity(ownerFieldsDto.getCity());
162	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
163	        currentOwner.setLastName(ownerFieldsDto.getLastName());
164	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
165	        this.clinicService.saveOwner(currentOwner);
166	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Transactional
171	    @Override
172	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        this.clinicService.deleteOwner(owner);
178	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        HttpHeaders headers = new HttpHeaders();
189	        Pet pet = petMapper.toPet(petFieldsDto);
190	        owner.setId(ownerId);
191	        pet.setOwner(owner);
192	        pet.getType().setName(null);
193	        this.clinicService.savePet(pet);
194	        PetDto petDto = petMapper.toPetDto(pet);
195	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
196	            .buildAndExpand(pet.getId()).toUri());
197	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
203	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
204	        if (currentOwner != null) {
205	            Pet currentPet = this.clinicService.findPetById(petId);
206	            if (currentPet != null) {
207	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
208	                currentPet.setName(petFieldsDto.getName());
209	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
210	                this.clinicService.savePet(currentPet);
211	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
212	            }
213	        }
214	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
220	        HttpHeaders headers = new HttpHeaders();
221	        Visit visit = visitMapper.toVisit(visitFieldsDto);
222	        Pet pet = new Pet();
223	        pet.setId(petId);
224	        visit.setPet(pet);
225	        this.clinicService.saveVisit(visit);
226	        VisitDto visitDto = visitMapper.toVisitDto(visit);
227	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
228	            .buildAndExpand(visit.getId()).toUri());
229	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
230	    }
231	
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner != null) {
238	            Pet pet = owner.getPet(petId);
239	            if (pet != null) {
240	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
241	            }
242	        }
243	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	    }
