277	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
278	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
279	            .map(Owner::getId)
280	            .min(Integer::compareTo)
281	            .orElse(null);
