3	import java.util.Map;
4	
5	/**
6	 * Maps a canonical region to its IANA timezone name via a fixed region-to-timezone table
7	 * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
8	 * {@code QLD -> Australia/Brisbane}).
9	 *
10	 * <p>The region is the locality derived by {@link LocalityResolver}; any region not present in the
11	 * table — including {@link LocalityResolver#UNKNOWN} and a {@code null} region — has no known
12	 * timezone.
13	 */
14	public final class TimezoneResolver {
15	
16	    /** Region -> IANA timezone; anything not listed has no known timezone. */
17	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
18	        "NSW", "Australia/Sydney",
19	        "VIC", "Australia/Melbourne",
20	        "QLD", "Australia/Brisbane");
21	
22	    private TimezoneResolver() {
23	    }
24	
25	    /**
26	     * Resolve the IANA timezone name for a region.
27	     *
28	     * @param region the canonical region, possibly {@code null}
29	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
30	     */
31	    public static String resolve(String region) {
32	        return REGION_TIMEZONE.get(region);
33	    }
34	}
