18	import java.time.LocalDate;
19	import java.time.Period;
20	
21	/**
22	 * A person's age band: {@link #MINOR} (under 18), {@link #ADULT} (18-64) or {@link #SENIOR}
23	 * (65 and over).
24	 */
25	public enum AgeBand {
26	
27	    MINOR, ADULT, SENIOR;
28	
29	    /**
30	     * Classifies the age band for someone born on {@code birthDate} as observed on
31	     * {@code asOf}, based on their completed years of age at that date.
32	     */
33	    public static AgeBand of(LocalDate birthDate, LocalDate asOf) {
34	        int years = Period.between(birthDate, asOf).getYears();
35	        if (years < 18) {
36	            return MINOR;
37	        }
38	        if (years < 65) {
39	            return ADULT;
40	        }
